int main() {
    int n;
    scanf("%d", &n);

    /* p 里存的是 n 的地址，不是 n 的值 */
    int *p = &n;

    printf("%d\n", n);    /* 直接访问变量 n */
    printf("%d\n", *p);   /* 顺着地址访问同一个 n，结果完全一样 */

    /* 注意：不要把地址本身打印出来（包括用地址专用的输出格式）。
       地址每次运行都可能不同，打印它既没有意义也没法判题，
       练习里我们只通过指针读写值。 */
    return 0;
}

