#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int *p = &n;

    printf("%d\n", *p);   /* 改之前，通过指针读一次 */

    *p = *p * 2;          /* *p 在等号左边 = 往 p 指向的那个变量里写 */

    printf("%d\n", n);    /* 直接读 n：它真的变了，因为 *p 就是 n */
    return 0;
}

