#include <stdio.h>

/* 参数是指针：函数拿到的是 a、b 的地址，所以能改到函数外面的变量。
   如果写成 void swap(int x, int y)，交换的只是副本，main 里的 a、b 一点没变。 */
void swap(int *x, int *y) {
    int t = *x;   /* 先把 x 指向的值存进临时变量 */
    *x = *y;      /* 把 y 指向的值写进 x 指向的那个房间 */
    *y = t;       /* 把临时变量写进 y 指向的房间 */
}

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    swap(&a, &b);   /* 传的是地址，不是值 */

    printf("%d\n%d\n", a, b);
    return 0;
}

