void bad_swap(int x, int y) {   /* 值传递：只换副本 */
    int t = x;
    x = y;
    y = t;
}

int main() {
    int a = 3, b = 8;
    bad_swap(a, b);
    printf("%d %d\n", a, b);   /* 还是 3 8 */
    return 0;
}

void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

/* 调用 */
swap(&a, &b);

