#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int a[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int sum = 0;

    /* 数组名 a 就是首元素的地址，等价于 &a[0]。
       p++ 让指针走到下一个 int（不是下一个字节）。 */
    for (int *p = a; p < a + n; p++) {
        sum += *p;     /* *p 就是当前这个元素 */
    }

    printf("%d\n", sum);
    return 0;
}

