#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int a[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 数组名 a 是首元素地址，p[i] 等价于 *(p + i)，也等价于 a[i] */
    int *p = a;
    int max = p[0];   /* 初值取第一个元素，数组全是负数也不会出错 */
    int idx = 0;

    /* 从第 2 个元素开始比。用 > 而不是 >=，
       遇到相同的最大值时不更新 idx，留下的就是第一次出现的下标。 */
    for (int i = 1; i < n; i++) {
        if (p[i] > max) {
            max = p[i];
            idx = i;
        }
    }

    printf("%d\n%d\n", max, idx);
    return 0;
}

