#include <stdio.h>

/* C 的函数只能返回一个值。想让函数「带回」两个结果，
   就把两个变量的地址传进去，函数通过指针往里面写。 */
void minmax(int *a, int n, int *pmax, int *pmin) {
    *pmax = a[0];   /* 初值取第一个元素，数组全是负数也不会算错 */
    *pmin = a[0];

    for (int i = 1; i < n; i++) {   /* 只遍历一次 */
        if (a[i] > *pmax) *pmax = a[i];
        if (a[i] < *pmin) *pmin = a[i];
    }
    /* 不需要 return 结果：写进 *pmax / *pmin，
       就等于写进了调用方那两个变量。 */
}

int main() {
    int n;
    scanf("%d", &n);

    int a[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int mx, mn;                /* 两个用来接结果的变量 */
    minmax(a, n, &mx, &mn);    /* 传数组首地址 + 两个变量的地址 */

    printf("%d\n%d\n%d\n", mx, mn, mx - mn);
    return 0;
}

